// ---------- run ----------
async function run() {
  progress("wavy — Pitch: preparing…");
  initColors();
  typeSpecs();
  await loadFonts();
  var page = figma.root.children.filter(function (p) { return p.name === PAGE_NAME; })[0];
  if (page) { await page.loadAsync(); page.children.slice().forEach(function (n) { n.remove(); }); }
  else { page = figma.createPage(); page.name = PAGE_NAME; }
  await figma.setCurrentPageAsync(page);
  page.backgrounds = [P("surface-2")];
  await buildStyles();
  progress("wavy — Pitch: design system…");
  var frames = [await buildDesignSystem()];
  var n0 = STATS.screens;
  frames.push(await buildStorefront()); STATS.storefront = STATS.screens - n0; n0 = STATS.screens;
  frames.push(await buildAccount()); STATS.account = STATS.screens - n0; n0 = STATS.screens;
  frames.push(await buildAdmin()); STATS.admin = STATS.screens - n0;
  frames.unshift(buildCover());
  await flush();
  var y = 0;
  frames.forEach(function (f) { page.appendChild(f); f.x = 0; f.y = y; y += f.height + 240; });
  figma.viewport.scrollAndZoomIntoView([frames[0]]);
  if (NOTE) NOTE.cancel();
  figma.closePlugin("wavy — Pitch: " + STATS.screens + " native screens (" + STATS.desktop + " desktop, " + STATS.mobile + " mobile), " + STATS.components + " components, " +
    Object.keys(PAINT_STYLES).length + " colour + " + Object.keys(TEXT_STYLES).length + " text styles." + (FONT_NOTES.length ? " Font notes are on the board (cover + design system)." : ""));
}

